function showDialog(title,message,icon='i'){$('#dialogTitle').textContent=title;$('#dialogMessage').textContent=message;$('#dialogIcon').textContent=icon;$('#xpDialog').hidden=false;$('#dialogOk').focus()}function closeDialog(){$('#xpDialog').hidden=true}function tasks(){$('#taskButtons').innerHTML='';openWindows.forEach(node=>{const b=document.createElement('button');b.className=`task-button${node.classList.contains('is-hidden')?'':' active'}`;b.textContent=$('.titlebar-title',node).textContent;b.onclick=()=>{node.classList.remove('is-hidden');focus(node)};$('#taskButtons').append(b)})}function focus(node){node.style.zIndex=String(++z);$$('.xp-window').forEach(item=>item.classList.remove('active'));node.classList.add('active');tasks()}
function drag(node){$('.titlebar',node).onpointerdown=e=>{if(e.target.closest('button')||node.classList.contains('maximized'))return;const r=node.getBoundingClientRect(),sx=e.clientX,sy=e.clientY;const move=n=>{node.style.left=`${Math.max(0,r.left+n.clientX-sx)}px`;node.style.top=`${Math.max(0,r.top+n.clientY-sy)}px`};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up)};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);e.preventDefault()}}
